document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".retour-haut");if(!e)return;const o=()=>{const o=window.scrollY>350;e.classList.toggle("visible",o)};window.addEventListener("scroll",o,{passive:!0}),e.addEventListener("click",()=>{const e=window.matchMedia("(prefers-reduced-motion: reduce)").matches;window.scrollTo({top:0,behavior:e?"auto":"smooth"})}),o()});